<script setup lang="ts">
import { computed, ref, watch } from 'vue';import { useRoute } from 'vue-router';import { ElMessage } from 'element-plus';import { http, type ApiResponse } from '../api/http'
interface Batch{batchNo:string;businessType:string;filename:string;status:string;total:number;success:number;failure:number;added:number;overwritten:number;skipped:number;summaryStatus:string|null;startedAt:string;finishedAt:string|null;errorMessage:string|null} interface ImportError{rowNumber:number;inpatientNo:string|null;admissionTimes:number|null;fieldName:string|null;originalValue:string|null;errorCode:string;errorMessage:string}
const route=useRoute(),loading=ref(false),rows=ref<Batch[]>([]),errors=ref<ImportError[]>([]),dialog=ref(false),current=ref<Batch|null>(null),businessType=computed(()=>String(route.meta.businessType||''));const fmt=(v:string|null)=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—'
const load=async()=>{loading.value=true;try{rows.value=(await http.get<ApiResponse<Batch[]>>('/import-batches',{params:{businessType:businessType.value}})).data.data}catch(e){ElMessage.error(e instanceof Error?e.message:'加载失败')}finally{loading.value=false}};const showErrors=async(row:Batch)=>{current.value=row;dialog.value=true;errors.value=[];try{errors.value=(await http.get<ApiResponse<ImportError[]>>(`/import-batches/${encodeURIComponent(row.batchNo)}/errors`)).data.data}catch(e){ElMessage.error(e instanceof Error?e.message:'加载失败')}};watch(businessType,load,{immediate:true})
</script>
<template><section class="page-card"><div class="page-heading"><div><h2>导入批次</h2><p>查看每次导入的处理结果；失败批次可展开定位到原始行和字段。</p></div><el-button :loading="loading" @click="load">刷新</el-button></div><el-table v-loading="loading" :data="rows" stripe class="data-table"><el-table-column prop="batchNo" label="批次号" min-width="170"/><el-table-column prop="filename" label="文件名" min-width="160" show-overflow-tooltip/><el-table-column prop="status" label="状态" width="100"/><el-table-column label="总数/成功/失败" width="150"><template #default="s">{{s.row.total}} / {{s.row.success}} / <span :class="{'danger-text':s.row.failure}">{{s.row.failure}}</span></template></el-table-column><el-table-column label="新增/覆盖/跳过" width="150"><template #default="s">{{s.row.added}} / {{s.row.overwritten}} / {{s.row.skipped}}</template></el-table-column><el-table-column label="开始时间" width="180"><template #default="s">{{fmt(s.row.startedAt)}}</template></el-table-column><el-table-column prop="errorMessage" label="批次错误" min-width="180" show-overflow-tooltip/><el-table-column label="操作" width="100"><template #default="s"><el-button v-if="s.row.failure||s.row.status==='FAILED'" link type="primary" @click="showErrors(s.row)">错误详情</el-button></template></el-table-column></el-table><el-dialog v-model="dialog" :title="`导入错误 · ${current?.batchNo||''}`" width="78%"><el-empty v-if="!errors.length" description="该批次没有逐行错误"/><el-table v-else :data="errors" max-height="520"><el-table-column prop="rowNumber" label="行号" width="70"/><el-table-column prop="inpatientNo" label="住院号" width="120"/><el-table-column prop="admissionTimes" label="住院次数" width="90"/><el-table-column prop="fieldName" label="字段" width="130"/><el-table-column prop="originalValue" label="原值" min-width="130" show-overflow-tooltip/><el-table-column prop="errorCode" label="错误码" width="150"/><el-table-column prop="errorMessage" label="错误说明" min-width="220"/></el-table></el-dialog></section></template>
